//! The snapshot of the MCP tool names. The export runs from `cargo test`,
//! like the IPC bindings, so a new or renamed tool rewrites the file and the
//! diff shows up in review. The handshake test checks the served list
//! against it, and `scripts/check-skills.mjs` reads it to judge the skills.

use std::path::PathBuf;

use super::tools::McpTools;

/// Compile time path, so the export never depends on the working folder.
pub const TOOL_NAMES_FILE: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tool-names.txt");

const HEADER: &str = "\
# Generated by `cargo test -p maquette-desktop`. Do not edit.
# Every tool the Maquette MCP server lists, one per line, sorted.
";

/// The snapshot's text: the header, then one tool name per line.
pub fn snapshot() -> String {
    let mut text = HEADER.to_string();
    for name in McpTools::tool_names() {
        text.push_str(&name);
        text.push('\n');
    }
    text
}

/// The tool names a snapshot lists, without its comment lines.
pub fn parse(text: &str) -> Vec<String> {
    text.lines()
        .map(str::trim)
        .filter(|line| !line.is_empty() && !line.starts_with('#'))
        .map(str::to_string)
        .collect()
}

/// Writes the snapshot to [`TOOL_NAMES_FILE`], when it changed. `rig.rs` in the
/// MCP tests includes the file, so a new modified time would rebuild them.
///
/// # Errors
///
/// Fails when the file cannot be written.
pub fn export() -> std::io::Result<()> {
    maquette_core::fs::write_if_changed(&PathBuf::from(TOOL_NAMES_FILE), &snapshot()).map(|_| ())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn export_writes_the_tool_names_beside_the_crate() {
        export().expect("export tool names");
        let text = std::fs::read_to_string(TOOL_NAMES_FILE).expect("read tool names");
        assert!(text.starts_with("# Generated by"));
        let names = parse(&text);
        assert_eq!(names, McpTools::tool_names());
        assert!(names.len() > 50, "only {} tools", names.len());
        assert!(names.iter().any(|n| n == "list_projects"));
    }
}
